"""Add original production diagnosis and multi-context synchronization content."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    title = by_path[path]['title'] if path in by_path else next((x['title'] for x in lessons if x['path'] == path), None)
    assert title is not None, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(title) + '</a>'

hubs = [
    dict(path='web-tech/production-signals-and-incident-decisions', title='Production Signals and Incident Decisions', summary='Connect a failed user action to bounded telemetry, service objectives, and a tested containment decision.', overview='A production incident is rarely a single exception. A case save may cross a browser, API, queue, and worker; each can report success while the final user action still fails. This track starts with the user-visible operation and follows its trace through asynchronous work. It sets measurable objectives, limits telemetry exposure and cardinality, and turns incident evidence into a containment or rollback decision. The goal is a reproducible diagnosis, not a dashboard filled with unrelated counters.', bridges=['web-tech/observability-and-recovery', 'web-tech/release-smoke-and-rollback', 'web-tech/telemetry-minimization-and-retention']),
    dict(path='web-tech/cross-tab-and-offline-data-coordination', title='Cross-Tab and Offline Data Coordination', summary='Reconcile browser contexts and disconnected edits without mistaking local state for server truth.', overview='One person can open two tabs, lose connectivity in one, and edit the same case from a second device. Local messages help tabs react quickly, but they do not establish durable order or authorization. This track uses scoped invalidation, a bounded offline outbox, snapshot-and-delta recovery, and explicit conflict decisions. Each operation carries a stable identity and a server-checked version. The UI distinguishes queued work, accepted writes, conflicts, and data that still needs a fresh read.', bridges=['web-tech/offline-sync-conflict-policy', 'web-tech/live-update-reconnect-and-order', 'web-tech/conditional-writes-and-lost-update-prevention']),
]

lessons = [
    dict(hub=0, path='web-tech/trace-context-across-request-and-job', title='Trace Context Across Requests and Jobs', summary='Follow one user action through HTTP and queued work without treating trace IDs as authorization.',
         definition='A trace relates operations that belong to one user action. The browser request, API handler, queue publish, worker execution, and result write each produce a span with a parent or linked context. A trace identifier is correlation data, not an access token; any incoming header is untrusted. Validate its shape, place strict limits on attributes, and create a trusted local operation identifier for decisions that require identity. When work crosses a queue, carry context in message metadata and record a link if the worker is not a direct child of the original request. Sampling can omit spans, so a missing span is not proof that a step never ran.',
         case='Case 47 is marked resolved. The API returns 202 after enqueuing an audit receipt, but the receipt never appears. A request log shows the browser request; a worker log uses a different identifier, so the team first blames the UI. Propagating a trace context through the queue links the acceptance and worker attempt. A separate stable operation ID proves which mutation the worker should apply. The worker rejected an outdated case version. The trace points to the failed boundary, while the version and authorization checks explain the outcome. Neither trace ID should appear in a public case export.',
         code='function safeTraceLabel(value) {\n  return /^[0-9a-f]{32}$/.test(value) && !/^0+$/.test(value) ? value : "untrusted";\n}\nconsole.log(safeTraceLabel("f".repeat(32)));\n// Output: ffffffffffffffffffffffffffffffff',
         implementation='The helper only illustrates strict shape checking; use a compliant propagation library for the full wire format and sampling flags. At ingress, reject malformed or oversized context and decide whether external context may continue across the trust boundary. Attach route templates and operation names to spans, not raw URLs containing case notes or tokens. A queued message needs both trace metadata and a business operation ID because tracing may be sampled or expire before replay. Emit one acceptance event and one terminal event for the durable job, with the same operation ID. Keep account and case authorization inside the worker; inherited trace metadata never grants permission.',
         cost='Creating a span is constant work per operation, but exporting every span across a high-volume request path can add network and storage cost proportional to request count and span depth. Sampling controls that cost; it also means an individual trace may be incomplete. Structured operation events can provide durable counts when traces are absent. Indexing a high-cardinality trace ID is appropriate for a short diagnostic window, whereas putting every user or case ID into a metric label can explode series count. Measure instrumentation overhead under load and test context propagation through retries and dead-letter paths.',
         failure='A developer copies the incoming trace header into an authorization context and lets an arbitrary external caller choose the account associated with a worker span. The trace is now both misleading and unsafe. Separate correlation from identity. Another failure starts a new trace at every queue retry, making one accepted operation look like unrelated jobs. Carry or link the original context and preserve the durable operation ID. If the trace collector is unavailable, the user write must still follow its normal acceptance contract; telemetry loss should be visible in diagnostics, not silently turn a successful write into a 500 response.',
         drill='Start a case 47 update, enqueue its receipt, retry the worker twice, and compare the trace graph with the durable operation log. Drop the collector and verify the user action still follows its normal outcome while a telemetry-loss signal rises. Send malformed and very long trace headers; no authorization or memory limit may depend on them. Replay a dead-letter message and verify its original operation ID remains stable. Inspect exported span attributes for raw note text, cookies, and access tokens, then remove any field that could leak private case data.',
         decision='Use trace context for bounded correlation and a separate operation ID for durable business work.',
         checks=['HTTP and queued work can be related without trusting caller-supplied identifiers.', 'A sampled or missing trace does not erase operation outcome evidence.', 'Span attributes exclude private payloads and authorization material.'],
         mistakes=['Using a trace ID as an authorization decision.', 'Starting unrelated traces on every queue retry.', 'Recording raw request bodies as span attributes.'],
         related=['web-tech/accepted-operations-and-status-resources', 'web-tech/signed-webhook-delivery-and-replay', 'web-tech/telemetry-minimization-and-retention']),
    dict(hub=0, path='web-tech/user-journey-slos-and-burn-alerts', title='User Journey SLOs and Burn Alerts', summary='Measure whether people can finish an operation and alert on meaningful error-budget loss.',
         definition='A service-level indicator is a measured fraction of good events among eligible events. Define good from the user action: a case save that commits and becomes visible, rather than an API gateway returning any 2xx response. A service-level objective names the target fraction over a window. Its error budget is the permitted bad fraction for that window. An alert should ask whether failures are spending that budget quickly enough to require action; a short and a long window together reduce noise from brief spikes while still catching sustained damage. Low-volume paths need special care because one failed request can dominate a short sample.',
         case='Reviewers save 4,700 cases in a rolling window. A new release returns 202 for every save, but 47 accepted operations never reach a final result. The API success graph appears healthy while the completed-save indicator falls. With a 99 percent target, 47 failures consume the entire allowed budget for those 4,700 events. The team pages on rapid budget spend only when both a short and a longer window show a real pattern. A separate ticket-level signal catches slow degradation. They segment by release and route but avoid creating one metric series per case ID.',
         code='function budgetState(total, bad, allowedBadBasisPoints) {\n  const allowance = Math.floor(total * allowedBadBasisPoints / 10000);\n  return { allowance, spent: bad, over: bad > allowance };\n}\nconsole.log(JSON.stringify(budgetState(4700, 47, 100)));\n// Output: {"allowance":47,"spent":47,"over":false}',
         implementation='The arithmetic illustrates the budget, not an alert rule. Record each eligible user operation once, including those accepted asynchronously, and define when it becomes good, bad, or still pending. Pending work must not be counted as good merely because it has not timed out yet. Choose a deadline that reflects the task. Keep the numerator and denominator aligned across browser, API, and worker signals, and deduplicate retries under one operation ID. Maintain separate indicators for latency and correctness if a fast wrong result is possible. Build alerts from rates over measured windows, include a minimum-volume rule, and send each alert to an owner with a runbook action.',
         cost='Computing a counter ratio is O(1) per event and O(k) storage for k bounded label combinations. Adding case ID, full URL, or customer ID as a label can make k grow with traffic and raise storage and query cost sharply. A longer window smooths noise but delays detection; a shorter window catches a fast outage but can page on tiny samples. Backfilling late job outcomes can revise a recent window, so the measurement pipeline needs a documented cutoff and correction policy. Compare alert detections with actual failed user journeys during drills rather than tuning only for attractive graphs.',
         failure='A dashboard divides HTTP 500s by all requests, including image fetches and health probes. The case-save job fails after a successful 202 response, so the dashboard reports near-perfect health. Define events at the user operation boundary, and track the accepted job to its terminal state. Another mistake pages whenever any one-minute sample has an error, waking responders for an isolated failure in a low-volume route. Require meaningful budget consumption across appropriate windows, with a distinct urgent rule for complete outages. Avoid suppressing every small route; small cohorts still need investigation paths.',
         drill='Simulate 4,700 case saves with 47 terminal failures and check that the allowed budget is exactly consumed within numeric tolerance. Send 47 retries for one operation and verify they count as one user journey. Delay job completion past its deadline and confirm it is not called good. Add a one-minute burst of two failures in a low-volume path and compare the short and long alert windows. Then hold a moderate failure rate for hours and verify a slower alert or ticket appears before the full window is exhausted.',
         decision='Measure a finished user task and alert on sustained, meaningful loss of its permitted failure budget.',
         checks=['Accepted but unfinished jobs are not counted as successful completion.', 'Retries do not inflate the eligible-operation denominator.', 'Metric labels have a bounded set of values and alerts name an owner.'],
         mistakes=['Equating HTTP acceptance with completed user success.', 'Adding case IDs as metric labels.', 'Paging from a tiny single-window sample without an action threshold.'],
         related=['web-tech/accepted-operations-and-status-resources', 'web-tech/field-and-lab-performance-evidence', 'web-tech/load-tests-and-capacity-budgets']),
    dict(hub=0, path='web-tech/telemetry-shapes-redaction-and-cardinality', title='Telemetry Shapes, Redaction, and Cardinality', summary='Keep event records useful for diagnosis while controlling data exposure and metric-series growth.',
         definition='Logs, metrics, and traces answer different questions. A structured event can preserve one operation outcome with a bounded event name, release, route template, duration, and error category. A metric aggregates counts or distributions across a limited set of labels. A trace links timed operations. None should ingest arbitrary user notes by default. Define an allowlist of fields for each signal at the point of creation; removing a secret after it reached a collector may be too late. Retention and access controls belong to the signal contract. Cardinality is the number of distinct label combinations, and it can rise multiplicatively when independent labels are combined.',
         case='A case-47 save fails only for release 29. A developer adds case ID, reviewer email, URL, and raw validation body to every metric label. One release produces thousands of series and exposes private note text in a monitoring system. A better design uses the route template, release identifier, outcome class, and bounded status code on the metric. The structured event retains a short internal operation ID under a shorter retention policy. A sampled trace shows which API or worker stage slowed down. Private payloads stay in the application record with normal access control.',
         code='function diagnosticFields(event) {\n  const allowed = ["operationId", "route", "release", "outcome"];\n  return Object.fromEntries(allowed.filter(key => event[key] !== undefined).map(key => [key, event[key]]));\n}\nconsole.log(JSON.stringify(diagnosticFields({ operationId: "op-47", route: "/cases/:id", release: "r29", outcome: "failed", note: "private" })));\n// Output: {"operationId":"op-47","route":"/cases/:id","release":"r29","outcome":"failed"}',
         implementation='The allowlist is an illustration. Production collection should also validate value length and shape, scrub exception messages that may contain payloads, and enforce a bounded enumeration for metric labels. Keep raw operation IDs out of metric dimensions, though short-lived logs may need them for correlation. Decide who can read each telemetry store and how long data remains there. Test the final exported payload after SDK and proxy enrichment, because automatic instrumentation can add headers or URLs that the application did not explicitly log. Redaction must happen before export, not only in a dashboard view.',
         cost='Writing one event is O(1) application work, but exporting and indexing n events consumes O(n) downstream storage. If a metric has label sets with sizes a, b, and c, the possible series count can approach a × b × c; even one unbounded label can dominate cost. Sampling traces saves storage but weakens single-request coverage. Very short retention lowers exposure and cost, yet can erase evidence before a delayed incident is discovered. Set retention by investigation need and data sensitivity, and test queries under realistic incident volume. Measure dropped events as its own bounded signal.',
         failure='An exception handler records error.stack plus serialized request.body. A failed upload now copies private case descriptions into a tracing service with broad employee access. An application-level filter removes body, but a reverse proxy still adds the full URL containing a query token. Review the complete exported event, configure auto-instrumentation, and replace raw URLs with route templates. Another failure gives every retry a unique error-name label; series counts grow until queries time out during the incident. Use stable error categories and keep detailed identifiers in access-controlled events.',
         drill='Submit a case note containing a marker that looks like a secret, then inspect logs, spans, metric labels, and collector exports for that marker. Generate 47,000 distinct case IDs and verify metric-series count remains close to the bounded route/outcome combinations. Cause a validation exception that includes input text and check that the exported error category remains useful without copying the text. Expire test events according to retention policy, then simulate a delayed incident and confirm the surviving aggregate evidence is sufficient to identify release and route.',
         decision='Allowlist and bound telemetry at creation, and keep detailed correlation out of metric dimensions.',
         checks=['Private payload markers do not reach any exported telemetry signal.', 'Metric series remain bounded as case count grows.', 'Release and route can still be isolated during a diagnosis.'],
         mistakes=['Logging an entire request object for convenience.', 'Treating dashboard redaction as source redaction.', 'Using unique operation IDs as metric labels.'],
         related=['web-tech/telemetry-minimization-and-retention', 'web-tech/browser-security-and-data-stewardship', 'web-tech/trace-context-across-request-and-job']),
    dict(hub=0, path='web-tech/incident-containment-and-evidence-timeline', title='Incident Containment and Evidence Timeline', summary='Choose a reversible containment action from a coherent timeline of user impact and releases.',
         definition='An incident response begins by establishing scope and stopping harm. Build a timeline from user-visible failures, release changes, service events, queue lag, and verified recovery checks. Timestamps from different systems can be skewed; sequence and operation IDs often give stronger ordering evidence than wall time alone. Containment may mean disabling a feature path, pausing a worker, reducing traffic, or rolling back a release. A rollback is safe only when its old code can still read current data and when queued jobs have a compatible consumer. Keep the decision, expected effect, and reversal condition visible to responders.',
         case='Release 29 changes the case receipt worker. At 14:07, completed-save failures rise; at 14:09, queue lag grows; by 14:12, reviewers have 62 unresolved receipts. The API still accepts new saves. Disabling only the receipt feature prevents new incomplete promises while preserving read access. The team checks whether release 28 can process messages written by release 29 before rolling back. A timeline lists the first bad operation ID, deployment event, containment action, backlog size, and the synthetic case-save result that proves recovery. A quiet error graph alone is not proof that pending work cleared.',
         code='function containmentChoice(currentWritesSafe, previousReaderCompatible) {\n  if (!currentWritesSafe) return "pause-writes";\n  return previousReaderCompatible ? "rollback-candidate" : "isolate-worker";\n}\nconsole.log(containmentChoice(true, false));\n// Output: isolate-worker',
         implementation='The helper is a decision sketch, not automatic incident control. A responder should verify user impact and blast radius, identify the suspect change, choose the smallest reversible action that stops further damage, and assign an owner to pending operations. Record evidence before changing systems when doing so will not delay containment. Test rollback compatibility against schema and queued-message versions; an old worker may misread new payloads. After containment, run the exact user journey that failed, confirm terminal operation outcomes, inspect backlog drain, and monitor for recurrence. A post-incident record should separate observed facts from hypotheses.',
         cost='A timeline adds O(n) review work for n relevant events; filtering to bounded operation and release identifiers keeps it tractable. Pausing a worker preserves data but increases queue age and storage; dropping messages reduces backlog at the cost of lost work and must have an explicit recovery rule. A rollback can restore behavior quickly yet fail if migrations or contracts are not backward compatible. A feature switch can contain one path but adds operational state that must be audited. Practice these actions ahead of an outage and measure time to detect, contain, and verify—not only time until a dashboard turns green.',
         failure='The team sees a spike after release 29 and immediately deploys release 28. The older worker reads a new message field incorrectly and marks 62 receipts complete without writing them. The apparent rollback deepens the incident. Check message and schema compatibility first, then isolate the worker if necessary. Another failure closes the incident when errors stop, ignoring accepted jobs already stuck in the queue. Include backlog and terminal operation counts in recovery evidence. If an action has no clear reversal condition, it can remain enabled for weeks and create a second failure mode.',
         drill='Inject a worker decode error after 29 accepted case saves. Write a timeline with first impact, release, queue lag, containment, and confirmed recovery. Attempt a rollback using an incompatible message fixture and verify the runbook blocks it. Pause writes only for the affected operation and keep unrelated reads available. Drain the backlog into a safe consumer, then check every accepted operation reaches a terminal state or explicit repair queue. Repeat with clock skew between API and worker logs, using sequence and operation IDs to reconstruct order.',
         decision='Contain the smallest failing path, then verify both new journeys and the backlog created before containment.',
         checks=['The timeline distinguishes facts from tentative causes.', 'Rollback is gated by schema and queued-message compatibility.', 'Recovery evidence includes pending operation outcomes, not just fresh traffic.'],
         mistakes=['Rolling back code without checking current data compatibility.', 'Treating a quiet error chart as proof that backlog is repaired.', 'Leaving a containment switch without an owner or reversal condition.'],
         related=['web-tech/release-smoke-and-rollback', 'web-tech/expand-and-contract-migrations', 'web-tech/accepted-operations-and-status-resources']),
    dict(hub=1, path='web-tech/cross-tab-invalidation-and-version-checks', title='Cross-Tab Invalidation and Version Checks', summary='Use same-origin tab messages to prompt a server read rather than as a durable source of truth.',
         definition='Two tabs may hold different snapshots of the same case. A same-origin message channel can tell other tabs that case 47 changed, but delivery is transient and depends on each context being open and listening. It does not replace a server version check or a fresh read. Send only a scoped invalidation identifier and version hint. A receiving tab should discard or mark its cached record stale, fetch the current authorized representation, and preserve unsaved local edits until the user chooses how to reconcile. A message from another tab is not permission to display private content in the current account context.',
         case='Tab A changes case 47 from Open to Resolved. Tab B is on the same origin with an unsaved note and an old version number. Tab A broadcasts a case-changed hint. Tab B does not overwrite its note with the hint; it marks the visible case status stale and fetches the current server version. A conditional save from Tab B receives a version conflict, and the editor offers a field comparison. If Tab B was closed during the broadcast, it still revalidates on focus or route return. A logout message clears local private caches but the server remains the authority for sessions.',
         code='function shouldRefresh(currentVersion, notice) {\n  return notice.caseId === 47 && notice.version > currentVersion;\n}\nconsole.log(shouldRefresh(6, { caseId: 47, version: 7 }));\n// Output: true',
         implementation='The predicate handles one case; a real listener also validates notice shape and account scope. A BroadcastChannel or storage event can carry the hint in supported contexts, but neither is a durable queue and neither guarantees an inactive tab heard the change. On focus and before sensitive mutation, revalidate against the server. Keep local unsaved fields separate from fetched server state. Include a generation token to ignore late responses for a previous account or route. Close listeners on teardown. A session transition should clear cached private data in every open context, while each request still relies on server-side authorization.',
         cost='Broadcasting one short hint is O(1) per change, and invalidating a keyed cache entry is O(1) on average. Refetching n open tabs can cause O(n) network requests; debounce repeated notices and avoid broadcasting every keystroke. Keeping full records in cross-tab messages increases transfer, privacy exposure, and merge ambiguity. Focus-based revalidation adds latency after tab return but catches missed messages. Measure stale-window duration and duplicate fetches under multiple tabs. Cross-device consistency remains a server synchronization problem, not a browser channel feature.',
         failure='A developer sends a whole case object through a channel and Tab B applies it directly to the editor. Tab B loses an unsaved note, and a tab still signed into an old account displays content it should not see. Send a narrow hint, scope it to the current session, and fetch authorized current data. Another defect assumes a closed tab received every message, so it never revalidates on return. Test tabs opened after the change and tabs suspended for an hour. Messages improve responsiveness; conditional writes prevent the lost update.',
         drill='Open two tabs on case 47 with version 6. Save version 7 in Tab A while Tab B contains an unsaved note. Confirm the note remains and the server status refreshes. Close Tab B before the next change and reopen it; it must recover without a missed message. Log out in Tab A and verify private cached data clears in Tab B, then try a stale API request and confirm server rejection. Flood 62 hints for the same version and measure deduplicated reads and listener cleanup.',
         decision='Broadcast invalidation hints, then let an authorized server read and versioned write establish truth.',
         checks=['Unsaved edits survive a cross-tab refresh.', 'A tab that missed a message revalidates on return.', 'Logout clearing is paired with server authorization on every request.'],
         mistakes=['Treating a browser message as a durable event log.', 'Broadcasting whole private records between tabs.', 'Applying a new snapshot over unsaved edits without a conflict path.'],
         related=['web-tech/client-cache-keys-and-invalidation', 'web-tech/conditional-writes-and-lost-update-prevention', 'web-tech/browser-security-and-data-stewardship']),
    dict(hub=1, path='web-tech/offline-outbox-idempotency-and-replay', title='Offline Outbox, Idempotency, and Replay', summary='Queue bounded mutations with stable keys and explicit accepted, conflicted, and rejected outcomes.',
         definition='An offline outbox stores intended writes until a network path is available. It is not a second server. Each queued operation needs a stable ID, account scope, target resource, expected version, payload, creation time, and retry state. The server must enforce authorization and idempotency when the same operation is replayed after an uncertain response. Replaying in order matters when later operations depend on earlier ones; independent operations may run concurrently within a limit. A browser online event only indicates possible connectivity, so the client must attempt the request and inspect its actual result. Background synchronization is optional and not uniformly available; foreground replay is a required fallback.',
         case='Reviewer 29 edits case 47 on a train. The page stores a status change as operation op-47 with expected version 6 and labels it Queued, not Saved. Connectivity returns and the server commits the write, but the response is lost. Retrying op-47 with the same idempotency key returns the original committed result rather than making a second audit entry. Meanwhile another reviewer may have saved version 7; in that case the queued write becomes Conflicted and remains available for review. A permanent authorization error becomes Rejected, never an infinite retry loop.',
         code='function replayDisposition(status) {\n  if (status === 412) return "conflicted";\n  if (status === 401 || status === 403) return "rejected";\n  return status >= 500 ? "retry-later" : "inspect-result";\n}\nconsole.log(replayDisposition(412));\n// Output: conflicted',
         implementation='The helper sketches status handling; production code must also distinguish a lost response from an unaccepted request, parse the operation receipt, and cap retries. Persist the outbox in transactional browser storage suitable for the payload size, encrypt or avoid sensitive data according to the product threat model, and clear account-scoped operations on logout only under an explicit recovery policy. Use an idempotency key bound server-side to the actor and exact request fingerprint, with a retention window longer than the expected replay horizon. Retry transient failure with backoff and deadlines; stop on conflict or permanent rejection. Show the user each pending operation and provide a way to discard or resolve it.',
         cost='Queueing n operations requires O(n) local storage and replay work. A bound on operation count and bytes prevents a long offline period from consuming unlimited device space. Serial replay preserves dependencies but increases catch-up time; bounded parallelism helps independent cases yet complicates ordering and rate limits. Server idempotency records also consume storage for their retention window. Browser eviction can erase local data, so the UI must not promise guaranteed delivery before server acceptance. Measure pending age, replay success, duplicate suppression, conflicts, and local storage failure.',
         failure='After a timeout, the client generates a new idempotency key for each retry. The first write actually committed, so later retries create duplicate audit records and notifications. Persist one key with the operation until terminal resolution. Another failure marks the queued change Saved when the online event fires, even though the server rejects its stale version. Separate Queued, Sending, Accepted, Conflicted, and Rejected states. A background sync handler may never run in one browser, so opening the app must also inspect and replay pending work with clear user feedback.',
         drill='Queue case 47 while offline and close the tab. Reopen under the same account, replay, and verify the operation ID is unchanged. Lose the first successful response, retry, and confirm one server audit record. Produce a 412 conflict and retain the local intent for review. Produce a 403 rejection and stop retries. Fill storage to its configured limit and show a usable error without claiming the new edit was saved. Repeat in a browser without background sync and verify foreground replay on return.',
         decision='Persist one stable operation identity and call an edit saved only after server acceptance.',
         checks=['A lost response followed by replay creates one server mutation.', 'Conflict and permanent rejection remain visible terminal states.', 'Foreground replay works when background synchronization is unavailable.'],
         mistakes=['Generating a new idempotency key for each retry.', 'Equating network availability with server acceptance.', 'Leaving an unbounded private outbox on a shared device.'],
         related=['web-tech/offline-sync-conflict-policy', 'web-tech/idempotent-write-requests', 'web-tech/conditional-writes-and-lost-update-prevention']),
    dict(hub=1, path='web-tech/snapshot-delta-cursor-and-gap-recovery', title='Snapshot, Delta Cursor, and Gap Recovery', summary='Combine a consistent snapshot with ordered changes and restart when a replay window is lost.',
         definition='A live view needs a starting snapshot and subsequent changes from a compatible point in the server log. Fetching a snapshot and then opening a change stream can leave a gap between those steps unless the snapshot carries a cursor or the stream can replay from a position tied to that snapshot. A delta cursor is a server-issued opaque position, not an array index invented by the client. Apply each change once, in order, and validate that it belongs to the same account, query, and authorization scope. If the replay window expires or a sequence gap appears, discard the cursor and fetch a new snapshot rather than pretending the view is current.',
         case='The case queue loads 62 rows and then subscribes to updates. During the two seconds between the list response and subscription, case 47 changes owner. A stream that begins only with new events misses the change, leaving a stale row forever. The server instead returns a snapshot with cursor c-29 and replays all changes after c-29. If the client reconnects after the cursor expires, it fetches a new snapshot and clears the old delta state. A filter change from Open to All also requires a new scope; reusing the old cursor may omit records or expose the wrong set.',
         code='function applyOrderedChange(lastSequence, change) {\n  if (change.sequence === lastSequence + 1) return change.sequence;\n  if (change.sequence <= lastSequence) return lastSequence;\n  throw new Error("gap-requires-snapshot");\n}\nconsole.log(applyOrderedChange(29, { sequence: 30 }));\n// Output: 30',
         implementation='The numeric helper illustrates gap detection. Real cursors can be opaque and may encode tenant, query, version, and expiry. The server should issue a snapshot and cursor with a consistent relationship, document replay retention, and reject a cursor for another account or filter. The client applies deduplicated changes to a keyed record store and keeps tombstones long enough to process deletes. A gap, rejected cursor, or changed query triggers a full scoped snapshot; an ordinary reconnect can use the last confirmed cursor. Announce stale state while recovering and avoid presenting a partially rebuilt list as authoritative.',
         cost='Applying n ordered deltas is O(n) work and can avoid repeatedly transferring a full m-record snapshot. Retaining a replay log costs server storage proportional to change volume and retention length. A full snapshot costs O(m) transfer and client reconciliation; it is the safe fallback after a gap. Tombstone storage also grows and needs compaction rules. A tiny replay window makes reconnects expensive, while an unbounded window raises server cost. Measure reconnection age, gap frequency, bytes transferred, and time until a fully current view, including permission and filter changes.',
         failure='The client loads a list at time T, opens a stream at T+2 seconds, and assumes no changes occurred in between. A case assignment from that interval is permanently missing. Use a cursor that links snapshot to replay. Another defect treats a sequence jump from 30 to 32 as a harmless dropped animation; the queue silently loses a case update. Stop applying deltas and fetch a new snapshot. A third defect reuses a cursor after a filter change, causing incorrect membership. Scope or invalidate cursors whenever the query or actor changes.',
         drill='Create a consistent 62-row snapshot with cursor c-29. Insert a case change between snapshot creation and stream subscription; verify replay includes it. Duplicate sequence 30, omit sequence 31, and inspect dedupe and gap recovery. Expire the cursor and ensure a fresh snapshot replaces stale data. Change the filter and actor while a reconnect is pending; old deltas must not enter the new view. Delete a case, replay the delete, and verify the tombstone prevents a late duplicate add from reviving it.',
         decision='Tie snapshots to replay positions, and recover from missing history with a fresh scoped snapshot.',
         checks=['A change between snapshot and subscription is not lost.', 'Duplicate or missing deltas have explicit outcomes.', 'Cursors cannot cross account or query boundaries.'],
         mistakes=['Opening a stream after a snapshot with no bridging cursor.', 'Ignoring sequence gaps as cosmetic issues.', 'Reusing a cursor for a different filter or account.'],
         related=['web-tech/live-update-reconnect-and-order', 'web-tech/stream-cancellation-and-partial-result-contract', 'web-tech/search-filters-and-result-cursors']),
    dict(hub=1, path='web-tech/collaborative-conflicts-and-presence-expiry', title='Collaborative Conflicts and Presence Expiry', summary='Separate editing presence from durable ownership and resolve concurrent changes at field scope.',
         definition='Presence tells others that a person may be viewing or editing a record. It is a short-lived signal, not a lock or proof that the person still holds an editor open. Give presence an expiry and treat disconnects as uncertain. Durable writes still need a server version, and concurrent edits need a conflict policy. Non-overlapping fields may be mergeable when the server validates each field against the same base version; two edits to the same field need a user decision or a domain-specific rule. A timestamp alone is a weak conflict resolver when clocks differ or an important edit would be silently overwritten.',
         case='Reviewers 29 and 62 open case 47. Reviewer 29 changes status; reviewer 62 types a private note. Their presence indicators refresh every few seconds, but a laptop sleep leaves reviewer 29 looking active until the lease expires. Both submit from version 6. The server accepts the first write as version 7 and rejects or merges the second according to field ownership. The note is never discarded merely because status changed; the UI shows the current server value beside the local intent. Presence informs collaboration, while the versioned mutation governs the record.',
         code='function conflictFields(local, remote) {\n  return Object.keys(local).filter(field => remote[field] !== undefined && remote[field] !== local[field]);\n}\nconsole.log(conflictFields({ status: "resolved", note: "check seal" }, { status: "open" }).join(","));\n// Output: status',
         implementation='The helper detects differing values in two objects, but real three-way merge also needs the shared base to distinguish concurrent edits from preexisting differences. Store base, local, and current server versions for a repair view. Validate each merged write server-side; the client cannot approve its own conflict resolution. Presence updates should be rate-limited, scoped to authorized collaborators, and expire automatically without requiring a perfect disconnect event. Avoid showing private details in the presence channel. If the product needs exclusive editing, implement an explicit server lease with renewal and expiry, plus a visible takeover path; a colored avatar is not that lease.',
         cost='Presence heartbeats add O(u) events per interval for u active editors, and naive fan-out to every collaborator can approach O(u²) delivery in a busy room. Rate limits, coalescing, and room scope reduce that load. A three-way field comparison costs O(f) for f fields, while rich-text merging can be much harder and may need a specialized data model. Server leases add writes and renewal traffic and can block progress when devices sleep. Measure false-active duration, conflict frequency, repair completion, and time lost to blocked editing rather than assuming more presence messages mean better collaboration.',
         failure='A presence avatar stays visible after a laptop loses connectivity, and the app treats it as an edit lock. Other reviewers cannot fix the case until an operator clears stale state. Give presence a short expiry and keep any real lease on the server. Another implementation applies last-write-wins by client timestamp; reviewer 62 has a clock three minutes ahead, so the note replaces reviewer 29’s later status without warning. Use server versions and a field-aware conflict view. If a merged result cannot be justified, preserve both intents and ask for a decision.',
         drill='Open case 47 in two sessions at version 6. Edit different fields and verify the chosen merge policy; then edit the same field and require explicit resolution. Sleep one client without a disconnect event and time the presence expiry. Change the device clock and confirm it cannot win a server version conflict by timestamp. Attempt presence subscription from an unauthorized account and inspect that no case details leak. If a server lease is added, let it expire and test a safe takeover without losing the original editor’s unsaved text.',
         decision='Let expiring presence inform people; let versioned server writes decide durable state.',
         checks=['Presence expires after a missing heartbeat and never acts as an implicit lock.', 'Same-field edits preserve both local intent and current server value.', 'Client clock skew cannot silently choose the winning edit.'],
         mistakes=['Treating a presence indicator as an exclusive edit lease.', 'Using client timestamps to overwrite meaningful concurrent edits.', 'Merging without a shared base version.'],
         related=['web-tech/conditional-writes-and-lost-update-prevention', 'web-tech/live-update-reconnect-and-order', 'web-tech/async-status-announcements-and-focus']),
]

